"""Deterministic text. Every value comes from stored measurements; a missing value renders as
'unavailable'. Nothing here is generated by a model."""
import datetime as dt


def fmt(v, pattern="{}"):
    return "unavailable" if v is None else pattern.format(v)


def falsifier(cls, today):
    d = lambda n: (today + dt.timedelta(days=n)).isoformat()  # noqa: E731
    if cls in ("inflection", "emerging"):
        return f"7-day star pace falls below 1.0x the 28-day pace, or no new artifacts, by {d(90)}"
    if cls == "resurgent":
        return f"ratio90 falls below 0.7 by {d(60)}"
    if cls == "climber":
        return f"ratio90 falls below 0.7 or share90 below 10% by {d(90)}"
    return f"class not {cls} by {d(90)}"


def why_now(m):
    if m.get("top_recent_story"):
        s = m["top_recent_story"]
        return f"HN story in the last 14 days: \"{s['title']}\" ({s['points']} points)"
    return "cause unexplained (treat as a warning)"


def alert_block(r, today):
    m = r["metrics"]
    lines = [f"{r['full_name']} — {r['class'].upper()} — score {r['score']}/100"]
    if m.get("surge_status") == "measured":
        lines.append(
            f"stars {fmt(m['stars'], '{:,}')} (GitHub, {m['observed_at']}) · "
            f"+{fmt(m['stars_last90'], '{:,}')} in 90d (share {fmt(m['share90'] and m['share90'] * 100, '{:.1f}%')}, "
            f"{fmt(m['ratio90'], '{:.2f}x')} prior 90d; exact stargazer timestamps)")
    else:
        lines.append(f"stars {fmt(m['stars'], '{:,}')} (GitHub, {m['observed_at']}) · "
                     f"surge test: {m.get('surge_status') or 'unavailable'}")
    arts = m.get("artifact_examples") or []
    lines.append(f"switching: {fmt(m.get('artifacts_new_120d'))} new artifacts in 120d"
                 + (f" e.g. {', '.join(arts[:2])}" if arts else ""))
    doms = m.get("domains_90d")
    lines.append("confirmation: " + (
        f"{len(doms)} independent domains in 90d ({', '.join(doms)})" if doms
        else ("0 independent domains in 90d" if doms == [] else "unavailable")))
    lines.append(f"shape: fork/star {fmt(m.get('fork_ratio') and m['fork_ratio'] * 100, '{:.1f}%')} · "
                 f"issues+PRs/star {fmt(m.get('issue_ratio') and m['issue_ratio'] * 100, '{:.1f}%')}")
    if r["class"] in ("resurgent", "climber"):
        lines.append(f"why now: {why_now(m)}")
    lines.append(f"falsifier: {falsifier(r['class'], today)}")
    lines.append(f"<https://github.com/{r['full_name']}>")
    return "\n".join(lines)


def notify_text(alerts, health_lines, dry_run, today, also_qualified):
    if not alerts and not health_lines:
        return ""
    parts = []
    if dry_run:
        parts.append("[DRY RUN — not recorded in the alert ledger]")
    if alerts:
        names = ", ".join(f"{r['full_name']} ({r['class']} {r['score']})" for r in alerts)
        parts.append(f"Softwatch: {len(alerts)} new — {names}")
        parts.extend(alert_block(r, today) for r in alerts)
    if also_qualified:
        parts.append("Also qualified (over the daily cap): " +
                     ", ".join(r["full_name"] for r in also_qualified))
    parts.extend(health_lines)
    return "\n\n".join(parts) + "\n"
